import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CFI7Wm0A.js";var i=JSON.parse(`{"title":"Key Concepts","description":"Choose the right identity type in WarpDrive internals: ResourceIdentifier, RecordIdentifier, or ResourceKey, based on whether lid is required and must be stable.","frontmatter":{"description":"Choose the right identity type in WarpDrive internals: ResourceIdentifier, RecordIdentifier, or ResourceKey, based on whether lid is required and must be stable."},"headers":[],"relativePath":"guides/contributing/key-concepts.md","filePath":"guides/contributing/key-concepts.md"}`),a={name:`guides/contributing/key-concepts.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to “Key Concepts”">​</a></h1><ul><li><a href="#identity">Identity</a></li></ul><hr><h2 id="identity" tabindex="-1">🔸 Identity <a class="header-anchor" href="#identity" aria-label="Permalink to “🔸 Identity”">​</a></h2><h3 id="working-with-identifiers-and-typescript" tabindex="-1">Working with Identifiers and TypeScript <a class="header-anchor" href="#working-with-identifiers-and-typescript" aria-label="Permalink to “Working with Identifiers and TypeScript”">​</a></h3><p>Identifying information can be encountered in several different manners depending on which APIs are being worked with and whether the code is &quot;internal&quot; or &quot;public facing&quot;.</p><ul><li>The &quot;ResourceIdentifier&quot; type is used when the identifying information is end-user-supplied and not guaranteed to have &quot;lid&quot;.</li></ul><p>Example: <code>findRecord({ type: &#39;user&#39;, id: &#39;1&#39; })</code></p><p>Most commonly this is the case when a record has not been encountered yet or when processing a payload received from the API.</p><ul><li>The &quot;RecordIdentifier&quot; type is used when identifying information MUST have &quot;lid&quot; but may not be the &quot;stable&quot; identifier object instance.</li></ul><p>Example: <code>saveRecord({ type: &#39;user&#39;, id: null, lid: &#39;user:1&#39; })</code></p><p>Most commonly this is the case when the user might manually construct an identifier. Often this is the result of having previously serialized record state and later attempting to restore it.</p><ul><li>The &quot;ResourceKey&quot; type is used when identifying information MUST have &quot;lid&quot; AND MUST be the &quot;stable&quot; identifier object instance produced and managed by the <code>CacheKeyManager</code> associated to a specific <code>Store</code> instance.</li></ul><p>Example:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> identifier</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> recordIdentifierFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(record);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unloadRecord</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(identifier);</span></span></code></pre></div><p>Any identifier supplied by a WarpDrive API will always be the stable variant. APIs which are operating based on identity and which can reasonably presume that the data exists expect stable identifiers and should error if an unknown identifier is encountered to prevent potential system-correctness errors.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};